<?php
$pid=(int)($user['parish_id']??0);$parish=$conn->execute_query('SELECT name FROM parishes WHERE id=?',[$pid])->fetch_assoc();
$isStaff=$user['role']!=='parishioner';
$rows=$conn->execute_query("SELECT a.*,p.name publisher_parish,u.role publisher_role FROM announcements a LEFT JOIN users u ON u.id=a.sent_by LEFT JOIN parishes p ON p.id=u.parish_id WHERE a.status='active' AND (NOT EXISTS(SELECT 1 FROM announcement_parishes ap WHERE ap.announcement_id=a.id) OR EXISTS(SELECT 1 FROM announcement_parishes ap JOIN parish_subscriptions ps ON ps.parish_id=ap.parish_id WHERE ap.announcement_id=a.id AND ps.user_id=? AND ps.in_app=1)) AND EXISTS (SELECT 1 FROM announcement_deliveries d WHERE d.announcement_id=a.id AND d.user_id=? AND d.channel='in-app' AND d.status='sent') ORDER BY COALESCE(a.sent_at,a.created_at) DESC",[$user['id'],$user['id']])->fetch_all(MYSQLI_ASSOC);
$page_id='announcements';$page_title='Announcements';require APP_ROOT.'/parishioner/includes/layout.php';
?><div class="card"><div class="card-body"><h2>Announcements</h2><?php if(!$rows):?><p>No announcements for your parish.</p><?php endif;?><?php foreach($rows as $row):?><article class="announcement-article"><small><?= h($row['publisher_role']==='admin'?'Admin':($row['publisher_parish']??'Parish')) ?> &middot; <?= h(display_datetime($row['sent_at']??$row['created_at'])) ?></small><h3><?=htmlspecialchars($row['title'])?></h3><p><?=nl2br(htmlspecialchars($row['content']))?></p><small><?=htmlspecialchars(display_datetime($row['sent_at']??$row['created_at']))?></small></article><?php endforeach;?></div></div><?php require APP_ROOT.'/parishioner/includes/layout_footer.php';?>
